    final Runnable flashOff=()->{if(flash!=null)flash.animate().alpha(0).setDuration(200).withEndAction(()->flash.setVisibility(View.GONE)).start();};
    void tapSeek(int seconds){if(player==null||!player.isSeekable()||duration<=0)return;long now=SystemClock.elapsedRealtime();tapTotal=now-tapAt<900&&Integer.signum(tapTotal)==Integer.signum(seconds)?tapTotal+seconds:seconds;tapAt=now;boolean hidden=controls.getVisibility()!=View.VISIBLE;seek(lastPosition+seconds);if(hidden){controls.setVisibility(View.GONE);handler.removeCallbacks(hide);}flash(tapTotal<0?"« "+PlayerPrefs.f("−%d s",-tapTotal):PlayerPrefs.f("+%d s",tapTotal)+" »",tapTotal<0?Gravity.LEFT:Gravity.RIGHT,700);}
    // Seek flashes stay left to right in Arabic so "« −10 ث" keeps its arrow on the side that was tapped.
